      .map((i) => i.value)
      .sort();
  }

  function arraysEqual(a, b) {
    if (a.length !== b.length) return false;
    return a.every((v, i) => v === b[i]);
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    let score = 0;
    const total = Object.keys(correct).length;

    for (const q of Object.keys(correct)) {
      const selected = getSelected(q);
      const expected = [...correct[q]].sort();
      if (arraysEqual(selected, expected)) score++;
    }

    status.classList.remove('success', 'error');
    status.classList.add(score === total ? 'success' : 'error');
    status.textContent = `You got ${score} of ${total} question${total === 1 ? '' : 's'} fully correct.`;
  });
})();
